"""
Exceptions for the Skills service.

"""

from qbraid_core.exceptions import HttpStatusMixin, QbraidException


class SkillsServiceRequestError(HttpStatusMixin, QbraidException):
    """Exception raised when a skills service API request fails."""


class SkillInstallError(QbraidException):
    """Exception raised when skill installation fails."""


class SkillNotFoundError(HttpStatusMixin, QbraidException):
    """Exception raised when a skill is not found."""
